SINA_SMART["pharma-asthma"] = {"lecture":"pharma-asthma","title":"Drugs for asthma and COPD","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"pharma-asthma:e0","text":"Asthma affects > 300 million people; most deaths in low-income countries.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"pharma-asthma:e1","text":"T2-high: eosinophilic, allergic, high IgE, steroid-responsive; T2-low: Th1/Th17, neutrophils, less steroid-responsive.","topic":"Asthma phenotypes","sec":1,"importance":"core","highYield":"untested"},{"id":"pharma-asthma:e2","text":"SABA (salbutamol, terbutaline): first line in acute attacks.","topic":"Bronchodilators","sec":2,"importance":"core","highYield":"untested"},{"id":"pharma-asthma:e4","text":"Tiotropium/ipratropium: caution in prostate enlargement, urinary obstruction, glaucoma.","topic":"Bronchodilators","sec":2,"importance":"core","highYield":"untested"},{"id":"pharma-asthma:e5","text":"ICS: first-line long-term control; rinse mouth to prevent thrush.","topic":"Anti-inflammatories","sec":3,"importance":"core","highYield":"untested"},{"id":"pharma-asthma:e6","text":"Montelukast: leukotriene receptor antagonist.","topic":"Anti-inflammatories","sec":3,"importance":"core","highYield":"untested"},{"id":"pharma-asthma:e7","text":"Theophylline: narrow window, many interactions, smoking raises clearance, TDM.","topic":"Anti-inflammatories","sec":3,"importance":"core","highYield":"untested"},{"id":"pharma-asthma:e8","text":"Roflumilast: PDE4 inhibitor for COPD.","topic":"Anti-inflammatories","sec":3,"importance":"core","highYield":"untested"},{"id":"pharma-asthma:e10","text":"Omalizumab = anti-IgE; mepolizumab/benralizumab = IL-5; dupilumab = IL-4/13; tezepelumab = TSLP.","topic":"SMART and biologics","sec":4,"importance":"core","highYield":"untested"},{"id":"pharma-asthma:e3","text":"LABA (salmeterol, formoterol): maintenance, with an ICS.","topic":"SMART and biologics","sec":4,"importance":"core","highYield":"untested"},{"id":"pharma-asthma:e9","text":"SMART: budesonide/formoterol as maintenance and reliever.","topic":"SMART and biologics","sec":4,"importance":"core","highYield":"untested"},{"id":"pharma-asthma:e11","text":"Use spacers with pMDIs; DPIs need a strong inspiration.","topic":"Inhaler devices","sec":5,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"1m6aipv":"a","1yvs4kx":"a","1njnmdv":"a","10m5a6g":"a","1pq3gfb":"a","1fx3yz4":"a","1e7kzlu":"a","1a1ygg8":"a","tzlysi":"a","11x9qyh":"a","dj259":"a","7q5mhe":"a","4i40r":"a","1k1trt7":"a","q32zdy":"a","1p5qz0t":"a","13dmojx":"a","1t6k9q3":"x"},"mapCounts":{"verified":0,"auto":17,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"pharma-asthma:e0":{"s":0,"u":["Asthma affects > 300 million people; most deaths in low-income countries.","Asthma is the commonest chronic disease, affecting over 300 million people ; most deaths occur in low- and lower-middle-income countries, where under-diagnosis and under-treatment are common."],"dp":[]},"pharma-asthma:e1":{"s":1,"u":["T2-high: eosinophilic, allergic, high IgE, steroid-responsive; T2-low: Th1/Th17, neutrophils, less steroid-responsive.","T2-high asthma (about half or more of patients): often childhood-onset, eosinophilic , allergen-driven with high IgE, frequent rhinitis, driven by Th2 cytokines; responds well to corticosteroids.","T2-low asthma (fewer than half): Th1 or Th17 activation, sometimes neutrophilic, usually not allergic, responds less to corticosteroids; mitochondrial dysfunction may contribute."],"dp":[]},"pharma-asthma:e2":{"s":2,"u":["SABA (salbutamol, terbutaline): first line in acute attacks.","SABAs : salbutamol (Ventoline), terbutaline (Bricanyl), fenoterol (Berotec): first line in acute asthma and exacerbations , and prevention of exercise-induced asthma."],"dp":[]},"pharma-asthma:e4":{"s":2,"u":["Tiotropium/ipratropium: caution in prostate enlargement, urinary obstruction, glaucoma.","Muscarinic antagonists : ipratropium, oxitropium (Tersigat), tiotropium (Spiriva) ; adverse effects include pharyngeal irritation and paradoxical bronchospasm (stop the drug); caution in benign prostatic enlargement, bladder outflow obstruction and glaucoma ."],"dp":[]},"pharma-asthma:e5":{"s":3,"u":["ICS: first-line long-term control; rinse mouth to prevent thrush.","ICS are the first-line long-term control treatment of persistent asthma; main adverse effect oropharyngeal candidiasis , prevented by rinsing the mouth."],"dp":[{"h":"Why an inhaled steroid, not a reliever, controls asthma","t":"Salbutamol relaxes the muscle but does nothing to the eosinophilic inflammation that drives attacks, so relying on it alone lets the disease progress and increases the risk of severe exacerbations. Inhaled corticosteroids reduce that inflammation, which is why they are first-line control and why SMART gives a dose of steroid every time the patient uses a reliever. Source: the lecture's ICS and SMART slides."}]},"pharma-asthma:e6":{"s":3,"u":["Montelukast: leukotriene receptor antagonist.","Leukotriene modifiers : montelukast (Singulair), a cysteinyl leukotriene receptor antagonist, for prophylaxis and chronic treatment, exercise-induced bronchospasm and allergic rhinitis symptoms (not first-line alone for allergic rhinitis, where intranasal corticosteroids are preferred)."],"dp":[]},"pharma-asthma:e7":{"s":3,"u":["Theophylline: narrow window, many interactions, smoking raises clearance, TDM.","Theophylline kinetics vary widely: clearance rises with smoking (active and passive) and low-carbohydrate high-protein diets; many drug interactions; therapeutic drug monitoring is recommended; avoid in cor pulmonale, heart failure or end-stage liver disease."],"dp":[{"h":"Why theophylline is used less today","t":"Its therapeutic window is narrow, its clearance varies with smoking, diet, age, illness and many interacting drugs, and toxic levels cause vomiting, arrhythmias and seizures. Inhaled drugs deliver bronchodilation and anti-inflammatory effect directly to the airways with far fewer systemic effects. Source: the lecture's phosphodiesterase inhibitor slides."}]},"pharma-asthma:e8":{"s":3,"u":["Roflumilast: PDE4 inhibitor for COPD.","Phosphodiesterase inhibitors : theophylline (non-selective; aminophylline IV) and roflumilast (PDE4, COPD)."],"dp":[]},"pharma-asthma:e10":{"s":4,"u":["Omalizumab = anti-IgE; mepolizumab/benralizumab = IL-5; dupilumab = IL-4/13; tezepelumab = TSLP.","Biologics for severe asthma: omalizumab (Xolair; anti-IgE, stops IgE binding mast cells and basophils; age 6 or more, positive allergy tests, IgE 30-700 IU/mL; SC every 2-4 weeks), mepolizumab (Nucala) and benralizumab (Fasenra) targeting the IL-5 pathway, dupilumab (Dupixent; anti-IL-4/13), tezepelumab (anti-TSLP)."],"dp":[]},"pharma-asthma:e3":{"s":4,"u":["LABA (salmeterol, formoterol): maintenance, with an ICS.","SMART (single maintenance and reliever therapy): one inhaler combining an ICS with the fast-onset LABA formoterol (budesonide/formoterol, Symbicort; mometasone/formoterol) used both daily and as needed; supported by the 2020 NHLBI and 2022 GINA guidelines, and it simplifies which inhaler to use."],"dp":[]},"pharma-asthma:e9":{"s":4,"u":["SMART: budesonide/formoterol as maintenance and reliever.","SMART (single maintenance and reliever therapy): one inhaler combining an ICS with the fast-onset LABA formoterol (budesonide/formoterol, Symbicort; mometasone/formoterol) used both daily and as needed; supported by the 2020 NHLBI and 2022 GINA guidelines, and it simplifies which inhaler to use."],"dp":[]},"pharma-asthma:e11":{"s":5,"u":["Use spacers with pMDIs; DPIs need a strong inspiration.","Pressurised metered-dose inhalers (conventional or breath-actuated), used with spacers / valved holding chambers to improve delivery; dry powder inhalers (single-dose, reusable, multidose such as Turbuhaler and Diskus for Flixotide and Seretide), which need a fast, deep inspiration; nebulisers (jet, ultrasonic, mesh)."],"dp":[]}},"meta":{"1m6aipv":{"a":"recall","vg":"pharma-asthma:e0/recall/1"},"1yvs4kx":{"a":"recall","vg":"pharma-asthma:e1/recall/1"},"1njnmdv":{"a":"recall","vg":"pharma-asthma:e2/recall/1"},"10m5a6g":{"a":"recall","vg":"pharma-asthma:e3/recall/1"},"1pq3gfb":{"a":"recall","vg":"pharma-asthma:e4/recall/1"},"1fx3yz4":{"a":"recall","vg":"pharma-asthma:e4/recall/2"},"1e7kzlu":{"a":"recall","vg":"pharma-asthma:e5/recall/1"},"1a1ygg8":{"a":"recall","vg":"pharma-asthma:e5/recall/2"},"tzlysi":{"a":"recall","vg":"pharma-asthma:e6/recall/1"},"11x9qyh":{"a":"recall","vg":"pharma-asthma:e7/recall/1"},"dj259":{"a":"recall","vg":"pharma-asthma:e7/recall/2"},"7q5mhe":{"a":"recall","vg":"pharma-asthma:e8/recall/1"},"4i40r":{"a":"recall","vg":"pharma-asthma:e3/recall/2"},"1k1trt7":{"a":"relationship","vg":"pharma-asthma:e3/relationship/1"},"q32zdy":{"a":"recall","vg":"pharma-asthma:e10/recall/1"},"1p5qz0t":{"a":"recall","vg":"pharma-asthma:e10/recall/2"},"13dmojx":{"a":"recall","vg":"pharma-asthma:e11/recall/1"}},"explRev":"f4bd5871a630"};
